<template><div class="left-sidebar"><div class="sidebar-search"><el-input v-model="searchText" size="small" placeholder="搜索配置项..." prefix-icon="el-icon-search" clearable @input="onSearch" /></div><div class="sidebar-nav"><div v-for="g in groups" :key="g.key" class="sidebar-nav-item" :class="{active:activeGroup===g.key}" @click="$emit('select-group',g.key)"><i :class="g.icon||'el-icon-menu'" class="nav-icon" /><span class="nav-name">{{groupTitle(g)}}</span><el-tag v-if="g.count" size="mini" class="nav-badge">{{g.count}}</el-tag></div></div><div class="sidebar-footer"><div class="sidebar-stat">共 {{totalGroups}} 组 · {{totalItems}} 项</div><div class="sidebar-footer-actions"><el-button size="mini" @click="$emit('reset')">恢复默认</el-button><el-button size="mini" type="primary" @click="$emit('save')">保存配置</el-button></div></div></div></template>
<script>export default{name:'LeftSidebar',props:{groups:{type:Array,default:()=>[]},activeGroup:{type:String,default:''},searchQuery:{type:String,default:''},totalGroups:{type:Number,default:0},totalItems:{type:Number,default:0}},emits:['select-group','search','save','reset'],data(){return{searchText:this.searchQuery,searchTimer:null}},watch:{searchQuery:{immediate:true,handler(v){this.searchText=v}}},methods:{onSearch(v){if(this.searchTimer)clearTimeout(this.searchTimer);this.searchTimer=setTimeout(()=>{this.$emit('search',v)},300)},groupTitle(g){return(g.title||'').replace(/第.*组·?\s*/,'').replace(/（\d+项）/, '').trim()}}}</script>
<style scoped>.left-sidebar{width:280px;min-width:280px;height:100%;background:#f5f7fa;border-right:1px solid #EBEEF5;display:flex;flex-direction:column;overflow:hidden}.sidebar-search{padding:12px 16px}.sidebar-search>>>.el-input__inner{height:40px;border-radius:10px;border:1px solid #e2e8f0}.sidebar-nav{flex:1;overflow-y:auto;padding:0 8px}.sidebar-nav-item{display:flex;align-items:center;padding:8px 14px;border-radius:8px;cursor:pointer;font-size:13.5px;font-weight:500;color:#475569;margin-bottom:2px;position:relative;transition:all .15s;min-height:40px}.sidebar-nav-item:hover{background:#f1f5f9}.sidebar-nav-item.active{background:#eef2ff;color:#4F46E5}.sidebar-nav-item.active::before{content:'';position:absolute;left:-8px;top:50%;transform:translateY(-50%);width:3px;height:20px;background:#4F46E5;border-radius:0 2px 2px 0}.nav-icon{font-size:16px;margin-right:12px;flex-shrink:0;color:inherit}.nav-name{flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.nav-badge{flex-shrink:0;margin-left:6px;background:#f1f5f9;color:#94a3b8;border:none}.sidebar-footer{padding:12px 16px;border-top:1px solid rgba(226,232,240,0.5);flex-shrink:0}.sidebar-stat{font-size:12px;color:#94a3b8;margin-bottom:8px;text-align:center}.sidebar-footer-actions{display:flex;gap:8px}.sidebar-footer-actions .el-button{flex:1;font-size:13px;font-weight:500;border-radius:8px}</style>
